</main></div><script>const search=document.getElementById('sf-search'),allRows=[...document.querySelectorAll('.stock-row')],empty=document.getElementById('sf-empty'),pager=document.getElementById('stock-pagination'),info=document.getElementById('stock-page-info');let page=1;const pageSize=12;function renderStock(){const q=(search?.value||'').toLowerCase().trim(),filtered=allRows.filter(row=>!q||row.dataset.search.includes(q)),pages=Math.max(1,Math.ceil(filtered.length/pageSize));page=Math.min(page,pages);allRows.forEach(row=>row.hidden=true);filtered.slice((page-1)*pageSize,page*pageSize).forEach(row=>row.hidden=false);empty.hidden=filtered.length!==0;info.textContent=filtered.length?`MENAMPILKAN ${(page-1)*pageSize+1}–${Math.min(page*pageSize,filtered.length)} DARI ${filtered.length} BARIS`:'TIDAK ADA DATA';pager.innerHTML='';for(let i=1;i<=pages;i++){const b=document.createElement('button');b.className='page-link '+(i===page?'active':'');b.textContent=i;b.type='button';b.onclick=()=>{page=i;renderStock()};pager.appendChild(b)}}search?.addEventListener('input',()=>{page=1;renderStock()});renderStock();</script></body></html>
